/**
 * Add plugin visibility to category action menus.
 *
 * @module     tool_pluginvisibility/category_actions
 * @copyright  2026 Patrick Thibaudeau
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

define(['jquery'], function($) {
    return {
        init: function() {
            // Find all category action menus
            $('.category-item-actions').each(function() {
                const actionMenu = $(this);
                const categoryItem = actionMenu.closest('.listitem-category');
                
                if (!categoryItem.length) {
                    return;
                }
                
                // Get category ID from data attribute
                const categoryId = categoryItem.data('id');
                
                if (!categoryId) {
                    return;
                }
                
                // Check if already added
                if (actionMenu.find('.action-pluginvisibility').length > 0) {
                    return;
                }
                
                // Create the URL
                const url = M.cfg.wwwroot + '/admin/tool/pluginvisibility/index.php?categoryid=' + categoryId;
                
                // Find the menu content
                const menuContent = actionMenu.find('.dropdown-menu');
                
                if (menuContent.length) {
                    // Create menu item HTML
                    const menuItem = $('<a>')
                        .attr('href', url)
                        .attr('class', 'dropdown-item action-pluginvisibility')
                        .attr('data-action', 'pluginvisibility')
                        .html('<i class="icon fa fa-cog fa-fw" aria-hidden="true"></i> Plugin visibility');
                    
                    // Add to menu
                    menuContent.append(menuItem);
                }
            });
        }
    };
});
